    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: proportional to remaining stream and current efficiency
        score = 15.0 + (mean_residual * 0.5) + (progress * 20.0);
    } else {
        // Best Fit Decreasing logic: penalize large post_residuals (wasted space)
        // Reward placements that result in a tight fit (post_residual near 0)
