    // 1. Best-Fit logic: prioritize bins that leave the smallest residual.
    // However, heavily penalize "near-misses" (residual < next_item_size if next_item_size > 0).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Penalize slots that are too small for the upcoming item.
            score += 50.0 + (next_item_size - post_residual) as f64 * 2.0;
        } else if post_residual == next_item_size {
            // Strong reward for perfect 2-step fit.
            score -= 40.0;
        }
    }

    // 2. Avoid fragmenting bins when we have many open bins.
    // If the post_residual is small but not zero, it creates "dead space" (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Prevent opening a new bin prematurely.
    // If this is a brand new bin (bin_residual == bin_capacity), penalize it 
    // unless no other bins can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // 4. Balance the packing density using the mean_residual.
    // If this bin's post_residual is significantly better than the current mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Progression adjustment: As we approach the end of the stream, 
    // prioritize tighter packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
