pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // We aim to minimize the score. 
    // 1. Base Score: Prefer tighter fits (lower post_residual).
    let mut score = post * post;

    // 2. Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that scales inversely with progress (we are more willing to open new bins early).
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64).powi(2) * (2.0 - progress);
    }

    // 3. Lookahead coupling:
    // If a future item exists, penalize post_residuals that are too small to fit the next item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post).powi(2) * 1.5;
        }
    }

    // 4. Global state coupling:
    // Penalize bins that deviate significantly from the mean_residual to keep bin distribution uniform.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    // 5. Scarcity reward:
    // If this is the only bin that can fit the current item, reward it to prevent opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= (bin_capacity as f64) * 2.0;
    }

    score
}

