pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1..10) that are unlikely to fit future items.
    // We use a sigmoid-like penalty for post_residual < 10.
    let gap_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Reward bins that tightly pack the current item, scaled by progress.
    // As the stream progresses, we become more aggressive in packing to avoid leaving bins half-empty.
    let tightness_reward = post * (0.5 + 0.5 * progress);

    // Lookahead logic: if next_item_size fits in this post_residual, prioritize this bin.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -20.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // We penalize this heavily unless the fitting_bins_count is low or the current bins are very full.
    let new_bin_penalty = if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64 * 10.0) / (1.0 + mean_residual);
        50.0 + (50.0 * (1.0 - progress)) - congestion
    } else {
        0.0
    };

    // Interaction term between current packing efficiency and the global state.
    let interaction = (post / (bin_capacity as f64)) * mean_residual;

    tightness_reward + gap_penalty + lookahead_bonus + new_bin_penalty + interaction
}
